{"description": "Extract PR Newswire search results", "command": "python3 - <<'EOF'
import re, html
with open('research/prn1.html', encoding='utf-8', errors='ignore') as f:
    content = f.read()
# Look for article links
links = re.findall(r'href="(/news-releases/[^"]+)"[^>]*>(.*?)</a>', content, re.S)
seen = set()
for url, title in links:
    t = html.unescape(re.sub(r'<[^>]+>', '', title)).strip()
    if url not in seen and t:
        seen.add(url)
        print(f"- {t}\n  https://www.prnewswire.com{url}")
    if len(seen) >= 20:
        break
if not seen:
    # try other patterns
    links2 = re.findall(r'href="(https://www\.prnewswire\.com/news-releases/[^"]+)"', content)
    for l in links2[:20]:
        print(l)
EOF"}

